import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';
import { transaction } from './db.ts';
import type { NewJob } from './validation.ts';

/** Time for one processing step. */
export const STEP_MS = 100;
/** Total attempts before a job is marked failed. */
export const MAX_ATTEMPTS = 3;
/** Wait before a failed attempt is retried (within the 250 ms – 2 s allowed). */
export const RETRY_DELAY_MS = 500;

/** A row of the `jobs` table. */
export interface JobRow {
  seq: number;
  id: string;
  status: 'queued' | 'running' | 'completed' | 'failed';
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  run_after: number;
  created_at: string;
  updated_at: string;
}

/** The public JSON shape of a job. */
export interface Job {
  id: string;
  status: JobRow['status'];
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function nowIso(): string {
  return new Date().toISOString();
}

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/** Typed wrapper around `prepare().get()`, which returns loosely typed records. */
export function one<T>(db: DatabaseSync, sql: string, ...params: (string | number | null)[]): T | undefined {
  return db.prepare(sql).get(...params) as unknown as T | undefined;
}

export function getJobRow(db: DatabaseSync, id: string): JobRow | undefined {
  return one<JobRow>(db, 'SELECT * FROM jobs WHERE id = ?', id);
}

export function listJobRows(db: DatabaseSync): JobRow[] {
  return db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
}

export type SubmitResult = { kind: 'created' | 'replayed'; job: Job } | { kind: 'conflict' };

/**
 * Creates a job, or, when an idempotency key is given, replays the job created with that key.
 * The check and the insert share one transaction, so a key never yields two jobs.
 */
export function submitJob(db: DatabaseSync, input: NewJob, key: string | undefined): SubmitResult {
  const fingerprint = JSON.stringify([input.input, input.steps, input.failAttempts]);
  return transaction(db, (): SubmitResult => {
    if (key !== undefined) {
      const existing = one<{ fingerprint: string; job_id: string }>(
        db,
        'SELECT fingerprint, job_id FROM idempotency_keys WHERE key = ?',
        key,
      );
      if (existing) {
        if (existing.fingerprint !== fingerprint) return { kind: 'conflict' };
        const row = getJobRow(db, existing.job_id);
        if (!row) throw new Error(`idempotency key ${key} refers to a missing job`);
        return { kind: 'replayed', job: toJob(row) };
      }
    }
    const id = randomUUID();
    const now = nowIso();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, run_after, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?)`,
    ).run(id, input.input, input.steps, input.failAttempts, now, now);
    if (key !== undefined) {
      db.prepare('INSERT INTO idempotency_keys (key, fingerprint, job_id) VALUES (?, ?, ?)').run(key, fingerprint, id);
    }
    const row = getJobRow(db, id);
    if (!row) throw new Error('inserted job not found');
    return { kind: 'created', job: toJob(row) };
  });
}

