export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface FieldError {
  field: string;
  message: string;
}

export type Parsed<T> = { ok: true; value: T } | { ok: false; fields: FieldError[] };

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

/** Returns the Idempotency-Key error, or undefined when the key is absent or valid. */
export function validateIdempotencyKey(key: string | undefined): FieldError | undefined {
  if (key === undefined || KEY_PATTERN.test(key)) return undefined;
  return { field: 'Idempotency-Key', message: 'must be 1 to 128 characters: letters, digits, "_" or "-"' };
}

/** Validates a POST /api/jobs request. `raw` is the body text as received. */
export function parseCreateJob(contentType: string | undefined, raw: string | undefined): Parsed<NewJob> {
  const mediaType = contentType?.split(';')[0]?.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    return fail([{ field: 'body', message: 'Content-Type must be application/json' }]);
  }
  if (raw === undefined) return fail([{ field: 'body', message: 'body is too large' }]);
  let body: unknown;
  try {
    body = JSON.parse(raw);
  } catch {
    return fail([{ field: 'body', message: 'body must be valid JSON' }]);
  }
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return fail([{ field: 'body', message: 'body must be a JSON object' }]);
  }
  const record = body as Record<string, unknown>;
  const errors: FieldError[] = [];

  for (const key of Object.keys(record)) {
    if (!ALLOWED_FIELDS.has(key)) errors.push({ field: key, message: 'unknown field' });
  }

  let input = '';
  const rawInput = record.input;
  if (rawInput === undefined) {
    errors.push({ field: 'input', message: 'is required' });
  } else if (typeof rawInput !== 'string') {
    errors.push({ field: 'input', message: 'must be a string' });
  } else if (rawInput.length < 1 || rawInput.length > 1000) {
    errors.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  } else if (rawInput.trim().length === 0) {
    errors.push({ field: 'input', message: 'must not be only whitespace' });
  } else {
    input = rawInput;
  }

  const steps = intField(record, 'steps', 1, 20, 5, errors);
  const failAttempts = intField(record, 'failAttempts', 0, 5, 0, errors);

  if (errors.length > 0) return fail(errors);
  return { ok: true, value: { input, steps, failAttempts } };
}

function intField(record: Record<string, unknown>, name: string, min: number, max: number, dflt: number, errors: FieldError[]): number {
  const value = record[name];
  if (value === undefined) return dflt;
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    errors.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return dflt;
  }
  if (value < min || value > max) {
    errors.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return dflt;
  }
  return value;
}

function fail<T>(fields: FieldError[]): Parsed<T> {
  return { ok: false, fields };
}

