import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase, initSchema } from './db.ts';
import { getJobRow, listJobRows, one, submitJob, toJob } from './jobs.ts';
import { parseCreateJob, validateIdempotencyKey } from './validation.ts';

/** A worker heartbeat older than this means the worker is down. */
const WORKER_STALE_MS = 3000;
/** Bodies larger than this are rejected; valid requests are far smaller. */
const MAX_BODY_BYTES = 64 * 1024;

const db = openDatabase();
initSchema(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: { field: string; message: string }[]): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

function readBody(req: IncomingMessage): Promise<string | undefined> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? undefined : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function workerIsUp(): boolean {
  const row = one<{ seen_at: number }>(db, "SELECT seen_at FROM worker_heartbeat WHERE name = 'worker'");
  return row !== undefined && Date.now() - row.seen_at <= WORKER_STALE_MS;
}

async function createJobRoute(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const rawKey = req.headers['idempotency-key'];
  const key = typeof rawKey === 'string' ? rawKey : undefined;
  const keyError = validateIdempotencyKey(key);
  const raw = await readBody(req);
  const parsed = parseCreateJob(req.headers['content-type'], raw);
  const fields = [...(keyError ? [keyError] : []), ...(parsed.ok ? [] : parsed.fields)];
  if (fields.length > 0 || !parsed.ok) {
    return sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
  }
  const result = submitJob(db, parsed.value, key);
  if (result.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, result.kind === 'created' ? 201 : 200, result.job);
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const methodNotAllowed = (allow: string) => sendError(res, 405, 'method_not_allowed', `Use ${allow} for this path.`, undefined, { Allow: allow } as never);

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed('GET');
    return send(res, 200, { status: 'ok', worker: workerIsUp() ? 'up' : 'down' });
  }
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed('GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      return send(res, 200, { jobs: listJobRows(db).map(toJob) });
    }
    if (method === 'POST') return createJobRoute(req, res);
    return methodNotAllowed('GET, POST');
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed('GET');
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No such job.');
    }
    const row = getJobRow(db, id);
    if (!row) return sendError(res, 404, 'not_found', 'No such job.');
    return send(res, 200, toJob(row));
  }
  sendError(res, 404, 'not_found', 'No such path.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});
server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

