import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, initSchema, transaction } from './db.ts';
import type { DatabaseSync } from 'node:sqlite';
import { MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, nowIso, one, type JobRow } from './jobs.ts';

/** How often the worker writes its heartbeat. */
const HEARTBEAT_MS = 1000;
/** How long an idle worker waits before checking the queue again. */
const IDLE_MS = 200;

const db = openDatabase();
initSchema(db);

let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

let lastBeat = 0;
function heartbeat(force = false): void {
  const now = Date.now();
  if (!force && now - lastBeat < HEARTBEAT_MS) return;
  lastBeat = now;
  db.prepare(
    `INSERT INTO worker_heartbeat (name, pid, seen_at) VALUES ('worker', ?, ?)
     ON CONFLICT (name) DO UPDATE SET pid = excluded.pid, seen_at = excluded.seen_at`,
  ).run(process.pid, now);
}

/**
 * Jobs left `running` by a worker that died are queued again. Their interrupted attempt still
 * counts in `attempts`, which is the number of attempts started.
 */
function recoverInterrupted(database: DatabaseSync): number {
  return database
    .prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'")
    .run(nowIso()).changes as number;
}

/** Takes the oldest queued job that is due and starts an attempt on it. */
function claimNext(database: DatabaseSync): JobRow | undefined {
  return transaction(database, () => {
    const row = one<JobRow>(
      database,
      "SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1",
      Date.now(),
    );
    if (!row) return undefined;
    database
      .prepare("UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE seq = ?")
      .run(nowIso(), row.seq);
    return { ...row, status: 'running', attempts: row.attempts + 1, progress_completed: 0 };
  });
}

function setProgress(seq: number, completed: number): void {
  db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE seq = ?').run(completed, nowIso(), seq);
}

function complete(job: JobRow): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE seq = ?",
  ).run(job.input.toUpperCase(), nowIso(), job.seq);
}

function fail(job: JobRow, error: string): void {
  db.prepare("UPDATE jobs SET status = 'failed', result_output = NULL, error = ?, updated_at = ? WHERE seq = ?").run(error, nowIso(), job.seq);
}

function requeueAfterDelay(job: JobRow): void {
  db.prepare("UPDATE jobs SET status = 'queued', run_after = ?, updated_at = ? WHERE seq = ?").run(Date.now() + RETRY_DELAY_MS, nowIso(), job.seq);
}

/**
 * Runs one attempt. Returns early without changing the job when the worker is stopping, so the
 * job stays `running` and is processed again after the next start.
 */
async function runAttempt(job: JobRow): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    // The simulated dependency fails at the first step, before any progress is made.
    await sleep(STEP_MS);
    if (stopping) return;
    if (job.attempts >= MAX_ATTEMPTS) fail(job, 'transient failure');
    else requeueAfterDelay(job);
    return;
  }
  for (let done = 1; done <= job.steps; done++) {
    await sleep(STEP_MS);
    if (stopping) return;
    setProgress(job.seq, done);
    heartbeat();
  }
  complete(job);
}

async function main(): Promise<void> {
  heartbeat(true);
  const recovered = recoverInterrupted(db);
  console.log(`worker started (recovered ${recovered} interrupted job(s))`);

  while (!stopping) {
    heartbeat();
    try {
      const job = claimNext(db);
      if (job) await runAttempt(job);
      else await sleep(IDLE_MS);
    } catch (e) {
      console.error('worker error:', e);
      await sleep(IDLE_MS);
    }
  }

  db.prepare("DELETE FROM worker_heartbeat WHERE name = 'worker'").run();
  db.close();
  console.log('worker stopped');
}

await main();

